// ═══════════════════════════════════════════════════════════════════════
// Recommendations — Conflict Resolver (2027 NEW)
//
// "The Arbiter" — Scheduling conflicts displayed as decision trees.
//
// Each conflict renders as a card with:
//   - Event A ↔ Event B header with severity badge
//   - Shared resources as chips
//   - Overlap time window
//   - AI suggestion summary
//   - Resolution branches (generated by generateConflictResolutions):
//     - Option label
//     - Feasibility score bar
//     - AI recommended badge
//     - Tradeoffs list
//     - Satisfaction impact indicator
//   - Recommended branch highlighted with glow
//
// Glass namespace: .glass-rcr
// ═══════════════════════════════════════════════════════════════════════

import { useState, useMemo } from "react";
import {
  AlertTriangle,
  CheckCircle2,
  ArrowRight,
  ArrowLeftRight,
  XCircle,
  ChevronDown,
  ChevronUp,
  ShieldAlert,
  Sparkles,
  ThumbsUp,
  ThumbsDown,
  Clock,
} from "lucide-react";

import type { SchedulingConflict, ConflictResolution } from "../types";
import {
  CONFLICT_SEVERITY_CONFIG,
  sortBySeverity,
  isBlockingConflict,
  isUrgentConflict,
} from "../types";

import { generateConflictResolutions } from "../lib/recommendationSynthesis";

import "./RecConflictResolver.css";
import { Button } from "@/shared/components/ui/Button";

// ═══════════════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════════════

interface RecConflictResolverProps {
  conflicts: SchedulingConflict[];
  reducedMotion: boolean;
  onSelectResolution?: (conflictId: string, resolutionId: string) => void;
  className?: string;
}

// ═══════════════════════════════════════════════════════════════════════
// RESOLUTION ICON RESOLVER
// ═══════════════════════════════════════════════════════════════════════

function getResolutionIcon(label: string): typeof ArrowRight {
  const lower = label.toLowerCase();
  if (lower.includes("reprogramar") || lower.includes("mover")) return Clock;
  if (lower.includes("compartir")) return ArrowLeftRight;
  if (lower.includes("cancelar")) return XCircle;
  return ArrowRight;
}

// ═══════════════════════════════════════════════════════════════════════
// OVERLAP FORMATTER
// ═══════════════════════════════════════════════════════════════════════

function formatOverlapWindow(start: string, end: string): string {
  try {
    const startDate = new Date(start);
    const endDate = new Date(end);
    const fmtOpts: Intl.DateTimeFormatOptions = {
      hour: "2-digit",
      minute: "2-digit",
      day: "2-digit",
      month: "short",
    };
    const startStr = startDate.toLocaleDateString("es", fmtOpts);
    const endStr = endDate.toLocaleTimeString("es", {
      hour: "2-digit",
      minute: "2-digit",
    });
    return `${startStr} – ${endStr}`;
  } catch {
    return `${start} – ${end}`;
  }
}

// ═══════════════════════════════════════════════════════════════════════
// SINGLE RESOLUTION BRANCH
// ═══════════════════════════════════════════════════════════════════════

interface BranchCardProps {
  resolution: ConflictResolution;
  index: number;
  totalBranches: number;
  isRecommended: boolean;
  reducedMotion: boolean;
  onSelect?: (resolutionId: string) => void;
}

function BranchCard({ resolution, index, isRecommended, reducedMotion, onSelect }: BranchCardProps) {
  const delayMs = reducedMotion ? 0 : index * 120;
  const BranchIcon = getResolutionIcon(resolution.option_label);
  return (
    <div
      className="rcr-branch"
      data-recommended={isRecommended ? "" : undefined}
      style={
        {
          "--stagger-i": index,
          "--branch-delay": `${delayMs}ms`,
        } as React.CSSProperties
      }
    >
      {/* ── Branch connector ──────────────────────────────────────────── */}
      <div className="rcr-branch-connector" aria-hidden="true">
        <div className="rcr-branch-line" />
        <div className="rcr-branch-node" />
      </div>

      {/* ── Branch content ────────────────────────────────────────────── */}
      <div className="rcr-branch-content">
        <div className="rcr-branch-header">
          <BranchIcon size={14} aria-hidden="true" className="rcr-branch-icon" />
          <span className="rcr-branch-label">{resolution.option_label}</span>
          {isRecommended && (
            <span className="rcr-branch-recommended">
              <Sparkles size={10} aria-hidden="true" />
              <span>IA Recomienda</span>
            </span>
          )}
        </div>

        <p className="rcr-branch-desc">{resolution.description}</p>

        {/* ── Feasibility bar ─────────────────────────────────────────── */}
        <div className="rcr-feasibility">
          <span className="rcr-feasibility-label">Factibilidad</span>
          <div className="rcr-feasibility-track">
            <div
              className="rcr-feasibility-fill"
              style={
                {
                  "--feasibility-pct": `${resolution.feasibility_score}%`,
                  "--fill-delay": `${delayMs + 150}ms`,
                } as React.CSSProperties
              }
              data-level={
                resolution.feasibility_score >= 75
                  ? "high"
                  : resolution.feasibility_score >= 50
                    ? "medium"
                    : "low"
              }
            />
          </div>
          <span className="rcr-feasibility-value">{resolution.feasibility_score}%</span>
        </div>

        {/* ── Satisfaction impact ─────────────────────────────────────── */}
        {resolution.satisfaction_impact !== undefined && (
          <div className="rcr-satisfaction">
            {resolution.satisfaction_impact >= 0 ? (
              <ThumbsUp size={11} aria-hidden="true" />
            ) : (
              <ThumbsDown size={11} aria-hidden="true" />
            )}
            <span className="rcr-satisfaction-label">Impacto satisfacción:</span>
            <span
              className="rcr-satisfaction-value"
              data-positive={resolution.satisfaction_impact >= 0 ? "" : undefined}
            >
              {resolution.satisfaction_impact >= 0 ? "+" : ""}
              {resolution.satisfaction_impact}
            </span>
          </div>
        )}

        {/* ── Tradeoffs ───────────────────────────────────────────────── */}
        {resolution.tradeoffs.length > 0 && (
          <div className="rcr-tradeoffs">
            <span className="rcr-tradeoffs-title">Trade-offs</span>
            <ul className="rcr-tradeoffs-list">
              {resolution.tradeoffs.map((t, i) => (
                <li key={i} className="rcr-tradeoff-item">
                  <ArrowRight size={9} aria-hidden="true" />
                  <span>{t}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* ── Select button (if recommended) ──────────────────────────── */}
        {isRecommended && onSelect && (
          <Button
            variant="unstyled"
            type="button"
            className="rcr-branch-select-btn"
            onClick={() => onSelect(resolution.id)}
          >
            <CheckCircle2 size={13} aria-hidden="true" />
            <span>Seleccionar opción</span>
          </Button>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════
// CONFLICT CARD — Full decision tree for one conflict
// ═══════════════════════════════════════════════════════════════════════

interface ConflictCardProps {
  conflict: SchedulingConflict;
  index: number;
  reducedMotion: boolean;
  onSelectResolution?: (conflictId: string, resolutionId: string) => void;
}

function ConflictCard({
  conflict,
  index,
  reducedMotion,
  onSelectResolution,
}: ConflictCardProps) {
  const [isExpanded, setIsExpanded] = useState(index === 0);
  const severityConfig = CONFLICT_SEVERITY_CONFIG[conflict.severity];
  const isBlocking = isBlockingConflict(conflict.severity);
  const isUrgent = isUrgentConflict(conflict.severity);
  const delayMs = reducedMotion ? 0 : index * 150;

  // Generate resolution options
  const resolutions = useMemo(
    () => generateConflictResolutions(conflict),
    [conflict],
  );

  resolutions.findIndex((r) => r.ai_recommended);

  return (
    <div
      className="rcr-conflict"
      data-severity={conflict.severity}
      data-blocking={isBlocking ? "" : undefined}
      data-urgent={isUrgent ? "" : undefined}
      style={
        {
          "--stagger-i": index,
          "--conflict-delay": `${delayMs}ms`,
        } as React.CSSProperties
      }
    >
      {/* ── Conflict header ────────────────────────────────────────────── */}
      <div className="rcr-conflict-header">
        <div className="rcr-conflict-events">
          <span className="rcr-event-name">{conflict.event_a_name}</span>
          <ArrowLeftRight size={14} aria-hidden="true" className="rcr-conflict-vs" />
          <span className="rcr-event-name">{conflict.event_b_name}</span>
        </div>
        <div className="rcr-conflict-badges">
          <span className="rcr-severity-badge" data-severity={conflict.severity}>
            {isBlocking && <ShieldAlert size={10} aria-hidden="true" />}
            <span>{severityConfig.label}</span>
          </span>
          <span className="rcr-type-badge">{conflict.conflict_type}</span>
        </div>
      </div>

      {/* ── Conflict details ───────────────────────────────────────────── */}
      <div className="rcr-conflict-details">
        {/* Overlap window */}
        <div className="rcr-overlap">
          <Clock size={12} aria-hidden="true" />
          <span className="rcr-overlap-label">Solapamiento:</span>
          <span className="rcr-overlap-value">
            {formatOverlapWindow(conflict.overlap_start, conflict.overlap_end)}
          </span>
        </div>

        {/* Shared resources */}
        {conflict.shared_resources.length > 0 && (
          <div className="rcr-resources">
            <span className="rcr-resources-label">Recursos compartidos:</span>
            <div className="rcr-resources-chips">
              {conflict.shared_resources.map((r) => (
                <span key={r} className="rcr-resource-chip">{r}</span>
              ))}
            </div>
          </div>
        )}

        {/* AI suggestion */}
        {conflict.suggestion && (
          <div className="rcr-suggestion">
            <Sparkles size={12} aria-hidden="true" />
            <span className="rcr-suggestion-text">{conflict.suggestion}</span>
          </div>
        )}
      </div>

      {/* ── Expand toggle ─────────────────────────────────────────────── */}
      <Button
        variant="unstyled"
        type="button"
        className="rcr-expand-btn"
        onClick={() => setIsExpanded((prev) => !prev)}
      >
        {isExpanded ? (
          <ChevronUp size={13} aria-hidden="true" />
        ) : (
          <ChevronDown size={13} aria-hidden="true" />
        )}
        <span>
          {isExpanded
            ? "Colapsar opciones"
            : `${resolutions.length} opciones de resolución`}
        </span>
      </Button>

      {/* ── Resolution branches ───────────────────────────────────────── */}
      {isExpanded && (
        <div className="rcr-branches">
          {resolutions.map((resolution, idx) => (
            <BranchCard
              key={resolution.id}
              resolution={resolution}
              index={idx}
              totalBranches={resolutions.length}
              isRecommended={resolution.ai_recommended}
              reducedMotion={reducedMotion}
              onSelect={
                onSelectResolution
                  ? (resId) => onSelectResolution(conflict.id, resId)
                  : undefined
              }
            />
          ))}
        </div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════
// MAIN COMPONENT
// ═══════════════════════════════════════════════════════════════════════

export function RecConflictResolver({
  conflicts,
  reducedMotion,
  onSelectResolution,
  className,
}: RecConflictResolverProps) {
  // Sort by severity (most severe first)
  const sortedConflicts = useMemo(
    () => sortBySeverity(conflicts),
    [conflicts],
  );

  // Summary counts
  const summary = useMemo(() => {
    const blocking = sortedConflicts.filter((c) =>
      isBlockingConflict(c.severity),
    ).length;
    const urgent = sortedConflicts.filter((c) =>
      isUrgentConflict(c.severity),
    ).length;
    return {
      total: sortedConflicts.length,
      blocking,
      urgent,
    };
  }, [sortedConflicts]);

  // ── Empty state ─────────────────────────────────────────────────────
  if (sortedConflicts.length === 0) {
    return (
      <div className={`glass-rcr ${className ?? ""}`} data-empty>
        <div className="rcr-header">
          <ShieldAlert size={16} aria-hidden="true" className="rcr-header-icon" />
          <span className="rcr-header-title">Resolución de Conflictos</span>
        </div>
        <div className="rcr-empty">
          <CheckCircle2 size={32} aria-hidden="true" className="rcr-empty-icon" />
          <p className="rcr-empty-text">
            Sin conflictos de programación detectados. Todos los eventos y
            recursos operan sin solapamiento.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className={`glass-rcr ${className ?? ""}`}>
      {/* ── Header ────────────────────────────────────────────────────── */}
      <div className="rcr-header">
        <ShieldAlert size={16} aria-hidden="true" className="rcr-header-icon" />
        <span className="rcr-header-title">Resolución de Conflictos</span>
        <span className="rcr-header-count">{summary.total}</span>
      </div>

      {/* ── Summary strip ─────────────────────────────────────────────── */}
      <div className="rcr-summary">
        {summary.blocking > 0 && (
          <div className="rcr-summary-item" data-variant="blocking">
            <ShieldAlert size={12} aria-hidden="true" />
            <span className="rcr-summary-value">{summary.blocking}</span>
            <span className="rcr-summary-label">bloqueantes</span>
          </div>
        )}
        {summary.urgent > 0 && (
          <div className="rcr-summary-item" data-variant="urgent">
            <AlertTriangle size={12} aria-hidden="true" />
            <span className="rcr-summary-value">{summary.urgent}</span>
            <span className="rcr-summary-label">urgentes</span>
          </div>
        )}
        <div className="rcr-summary-item" data-variant="total">
          <span className="rcr-summary-label">Total:</span>
          <span className="rcr-summary-value">{summary.total}</span>
        </div>
      </div>

      {/* ── Conflict cards ────────────────────────────────────────────── */}
      <div className="rcr-body">
        {sortedConflicts.map((conflict, idx) => (
          <ConflictCard
            key={conflict.id}
            conflict={conflict}
            index={idx}
            reducedMotion={reducedMotion}
            onSelectResolution={onSelectResolution}
          />
        ))}
      </div>
    </div>
  );
}